11	export function parsePlaceOrderRequest(body: unknown): NewOrder {
12	  if (!isJsonObject(body)) {
13	    throw new ValidationError([{ path: "body", message: "must be a JSON object" }]);
14	  }
15	  const reader = new InputReader(body);
16	  const customerId = reader.string("customerId");
17	  const customerEmail = reader.string("customerEmail");
18	  const channel = reader.string("channel");
19	  const currency = reader.string("currency");
20	
21	  const lines: OrderLine[] = [];
22	  reader.array("lines").forEach((raw, index) => {
23	    const line = reader.object(`lines[${index}]`, raw);
24	    if (line === undefined) {
25	      return;
26	    }
27	    lines.push({
28	      sku: line.string("sku"),
29	      name: line.string("name"),
30	      qty: line.number("qty"),
31	      unitPriceCents: line.number("unitPriceCents"),
32	    });
33	    reader.issues.push(...line.issues);
34	  });
35	
36	  if (reader.issues.length > 0) {
37	    throw new ValidationError(reader.issues);
38	  }
39	  // The core validates that `channel` is one of the supported values.
40	  return { customerId, customerEmail, channel: channel as Channel, currency, lines };
